O=Path(__file__).resolve().parent;entries=json.loads((O/'hook-headlines.json').read_text());f=ImageFont.truetype('/System/Library/Fonts/Supplemental/Arial Bold.ttf',60)
code="local r=fu:GetResolve();local pm=r:GetProjectManager();local p=pm:GetCurrentProject();assert(not p:IsRenderingInProgress());assert(pm:SaveProject());if p:GetName()~='MOT-UGC-YAPPER-01 v7 V3 20260910' then p=pm:LoadProject('MOT-UGC-YAPPER-01 v7 V3 20260910');assert(p) end;local mp=p:GetMediaPool();local jobs={};local function find(name) for i=1,p:GetTimelineCount() do local t=p:GetTimelineByIndex(i);if t:GetName()==name then return t end end end;"
for e in entries:
 h=e['hook'];png=O/'titles'/f'{h}-headline.png';mov=png.with_suffix('.mov');im=Image.new('RGBA',(1080,1920));d=ImageDraw.Draw(im);w=f.getlength(e['text']);assert w<980;left=(1080-w)/2;top=e['top'];box=f.getbbox(e['text']);d.rounded_rectangle((left-20,top-12,left+w+20,top+69),radius=12,fill='white');d.text((left,top-box[1]),e['text'],font=f,fill='black');im.save(png);subprocess.run(['ffmpeg','-v','error','-y','-loop','1','-framerate','30','-i',str(png),'-frames:v',str(e['end']+3),'-an','-c:v','qtrle','-pix_fmt','argb','-threads','1',str(mov)],check=True)
 code+=f'''do local source=find({json.dumps(e['source_timeline'])});assert(source);local t=find({json.dumps(e['target_timeline'])});if not t then t=source:DuplicateTimeline({json.dumps(e['target_timeline'])});assert(t);assert(p:SetCurrentTimeline(t));assert(t:AddTrack('video'));local m=mp:ImportMedia({{{json.dumps(str(mov))}}})[1];assert(m);local c=mp:AppendToTimeline({{{{mediaPoolItem=m,startFrame=0,endFrame={e['end']},recordFrame=0,trackIndex=4,mediaType=1}}}})[1];assert(c and c:GetStart()==0 and c:GetEnd()=={e['end']});t:SetTrackName('video',4,'Upper middle hook headline') end;assert(p:SetCurrentTimeline(t));assert(t:GetEndFrame()=={e['total_frames']});assert(#t:GetItemListInTrack('video',4)==1);assert(#t:GetItemListInTrack('video',2)==32);assert(pm:SaveProject());assert(t:Export({json.dumps(str(O/f'project-files/Motilli-V30-{h}-FINAL.drt'))},r.EXPORT_DRT));print('V30_NATIVE','{h}',t:GetEndFrame());p:SetCurrentRenderMode(1);assert(p:SetCurrentRenderFormatAndCodec('mp4','H264'));assert(p:SetRenderSettings({{TargetDir={json.dumps(str(O/'deliverables'))},CustomName='Motilli-VSL-V30-{h}-HOOK-CAPTION-1.2x',SelectAllFrames=true,ExportVideo=true,ExportAudio=true,FormatWidth=1080,FormatHeight=1920,FrameRate=30,VideoQuality=16000,AudioCodec='aac',AudioBitDepth=16,AudioSampleRate=48000}}));local id=p:AddRenderJob();assert(id);table.insert(jobs,id);print('V30_JOB','{h}',id) end;'''
code+=f"assert(pm:SaveProject());assert(pm:ExportProject(p:GetName(),{json.dumps(str(O/'project-files/Motilli-V30-FINAL.drp'))}));assert(p:StartRendering(jobs));print('V30_RENDER_STARTED')"
